mapper.select:
/* com.portal.user.help.faq.FaqManageMapper.selectFaqList */ SELECT FAQ_ID AS faqId, QESTN_SJ AS qestnSj, QESTN_CN AS qestnCn, ANSWER_CN AS answerCn, RDCNT AS inqireCo, ATCH_FILE_ID AS atchFileId, DATE_FORMAT(FRST_REGIST_PNTTM, '%Y-%m-%d') AS frstRegisterPnttm, FRST_REGISTER_ID AS frstRegisterId, DATE_FORMAT(LAST_UPDT_PNTTM, '%Y-%m-%d') AS lastUpdusrPnttm, LAST_UPDUSR_ID AS lastUpdusrId FROM LETTNFAQINFO WHERE 1 = 1
AND QESTN_SJ LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY FAQ_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.update:
/* com.portal.user.help.faq.FaqManageMapper.updateFaqInqireCo */
UPDATE LETTNFAQINFO
   SET RDCNT           = IFNULL(RDCNT, 0) + 1,
       LAST_UPDT_PNTTM = SYSDATE(),
       LAST_UPDUSR_ID  = #{lastUpdusrId}
 WHERE FAQ_ID = #{faqId}

/* com.portal.user.help.faq.FaqManageMapper.updateFaqCn */
UPDATE LETTNFAQINFO
   SET QESTN_SJ        = #{qestnSj},
       QESTN_CN        = #{qestnCn},
       ANSWER_CN       = #{answerCn},
       ATCH_FILE_ID    = #{atchFileId},
       LAST_UPDT_PNTTM = SYSDATE(),
       LAST_UPDUSR_ID  = #{lastUpdusrId}
 WHERE FAQ_ID = #{faqId}
